import json, time, urllib.parse, urllib.request
seen = {}
for term in ['tennis', 'padel', 'pickleball', 'squash', 'badminton']:
    url = 'https://itunes.apple.com/search?' + urllib.parse.urlencode(
        {'term': term, 'entity': 'software', 'country': 'us', 'limit': 200})
    for app in json.load(urllib.request.urlopen(url))['results']:
        seen[app['trackId']] = app
    time.sleep(3)
print(len(seen), 'distinct apps')
